<?php
function diarioStorage(){return defined('DIARIO_UPLOAD_DIR')?DIARIO_UPLOAD_DIR:dirname(__DIR__,3).'/diario-private';}
function diarioImageType($path,$name){
 $mime=(new finfo(FILEINFO_MIME_TYPE))->file($path);$ext=strtolower(pathinfo($name,PATHINFO_EXTENSION));
 $raw=['raw','cr2','cr3','nef','arw','dng','orf','rw2','raf','heic','heif','psd','ai','eps'];
 if(strpos($mime,'image/')!==0&&!($mime==='application/octet-stream'&&in_array($ext,$raw,true))&&!($mime==='application/postscript'&&in_array($ext,['ai','eps'],true)))throw new InvalidArgumentException('El archivo no se reconoce como imagen.');
 return $mime;
}
function diarioRegisterAttachments($app,$auth){
 $app->get('/diario/tareas/{id:[0-9]+}/adjuntos',function($q,$r,$args){$i=$q->getAttribute('diario');$t=diarioTask($this->db,$args['id'],$i);$s=$this->db->prepare('SELECT Id,Tarea,Nombre,Mime,Tamano,Usuario,Fecha FROM Rhu_DiarioAdjunto WHERE Tarea=? ORDER BY Id');$s->execute([$t['Id']]);$locked=$t['Calidad']!==null||$t['Estado']==='cancelada';$items=$s->fetchAll(PDO::FETCH_ASSOC);foreach($items as &$a){$a['VistaPrevia']=in_array($a['Mime'],['image/jpeg','image/png','image/gif','image/webp','image/avif','image/bmp'],true);$a['PuedeEliminar']=!$locked&&($i['admin']||$a['Usuario']===$i['user']);}return $r->withJson(['adjuntos'=>$items,'bloqueado'=>$locked]);})->add($auth);
 $app->post('/diario/tareas/{id:[0-9]+}/adjuntos',function($q,$r,$args){
  $db=$this->db;$i=$q->getAttribute('diario');$db->beginTransaction();$t=diarioTask($db,$args['id'],$i,true);if($t['Calidad']!==null||$t['Estado']==='cancelada')throw new InvalidArgumentException('Los adjuntos de una actividad evaluada o cancelada quedan protegidos.');
  $s=$db->prepare('SELECT COUNT(*) FROM Rhu_DiarioAdjunto WHERE Tarea=?');$s->execute([$t['Id']]);if((int)$s->fetchColumn()>=20)throw new InvalidArgumentException('Máximo 20 imágenes por actividad.');
  $f=$q->getUploadedFiles()['imagen']??null;if(!$f||$f->getError()!==UPLOAD_ERR_OK)throw new InvalidArgumentException('No se recibió la imagen. Máximo 20 MB por archivo.');if($f->getSize()<1||$f->getSize()>20*1024*1024)throw new InvalidArgumentException('Máximo 20 MB por imagen.');
  $name=basename(str_replace('\\','/',$f->getClientFilename()));$name=mb_substr(preg_replace('/[\x00-\x1f\x7f]/u','',$name),0,255);if(!$name)throw new InvalidArgumentException('Nombre de imagen inválido.');
  $stream=$f->getStream();$uri=$stream->getMetadata('uri');if(!is_string($uri)||!is_file($uri))throw new InvalidArgumentException('No se pudo leer la imagen.');$mime=diarioImageType($uri,$name);$key=bin2hex(random_bytes(32));$dir=diarioStorage();if(!is_dir($dir)&&!mkdir($dir,0700,true))throw new RuntimeException('private storage');$path=$dir.'/'.$key;
  try{$f->moveTo($path);$s=$db->prepare('INSERT INTO Rhu_DiarioAdjunto(Tarea,Nombre,Archivo,Mime,Tamano,Usuario,Fecha) VALUES(?,?,?,?,?,?,?)');$s->execute([$t['Id'],$name,$key,$mime,$f->getSize(),$i['user'],diarioNow()]);$id=(int)$db->lastInsertId();diarioEvent($db,$t['Id'],$i['user'],'adjunto','Imagen añadida: '.$name);$db->commit();return $r->withJson(['Id'=>$id]);}catch(Throwable $e){if(is_file($path))unlink($path);throw $e;}
 })->add($auth);
 $app->get('/diario/adjuntos/{id:[0-9]+}',function($q,$r,$args){$i=$q->getAttribute('diario');$s=$this->db->prepare('SELECT * FROM Rhu_DiarioAdjunto WHERE Id=?');$s->execute([(int)$args['id']]);$a=$s->fetch(PDO::FETCH_ASSOC);if(!$a)throw new InvalidArgumentException('Imagen no disponible.');diarioTask($this->db,$a['Tarea'],$i);if(!preg_match('/^[a-f0-9]{64}$/',$a['Archivo']))throw new RuntimeException('storage key');$path=diarioStorage().'/'.$a['Archivo'];if(!is_file($path))throw new InvalidArgumentException('El archivo ya no está disponible.');$preview=($q->getQueryParams()['vista']??'')==='1'&&in_array($a['Mime'],['image/jpeg','image/png','image/gif','image/webp','image/avif','image/bmp'],true);$r=$r->withBody(new \Slim\Http\Stream(fopen($path,'rb')));return $r->withHeader('Content-Type',$preview?$a['Mime']:'application/octet-stream')->withHeader('Content-Disposition',($preview?'inline':'attachment')."; filename=\"imagen\"; filename*=UTF-8''".rawurlencode($a['Nombre']))->withHeader('X-Content-Type-Options','nosniff')->withHeader('Content-Security-Policy',"sandbox; default-src 'none'");})->add($auth);
 $app->post('/diario/adjuntos/{id:[0-9]+}/eliminar',function($q,$r,$args){$db=$this->db;$i=$q->getAttribute('diario');$db->beginTransaction();$s=$db->prepare('SELECT * FROM Rhu_DiarioAdjunto WHERE Id=?');$s->execute([(int)$args['id']]);$a=$s->fetch(PDO::FETCH_ASSOC);if(!$a)throw new InvalidArgumentException('Imagen no disponible.');$t=diarioTask($db,$a['Tarea'],$i,true);if($t['Calidad']!==null||$t['Estado']==='cancelada'||(!$i['admin']&&$a['Usuario']!==$i['user']))throw new InvalidArgumentException('No puedes eliminar esta evidencia.');$s=$db->prepare('DELETE FROM Rhu_DiarioAdjunto WHERE Id=?');$s->execute([$a['Id']]);diarioEvent($db,$t['Id'],$i['user'],'adjunto_eliminado',$a['Nombre']);$db->commit();if(preg_match('/^[a-f0-9]{64}$/',$a['Archivo']))@unlink(diarioStorage().'/'.$a['Archivo']);return $r->withJson(['ok'=>true]);})->add($auth);
}
